import {
  SITE_NAME,
  TAGLINE,
  FOOTER_LINE,
  COPYRIGHT,
  CONTACT_EMAIL,
  NAV_LINKS,
  CTA,
  PAGE_TITLES,
  getPageTitle,
} from '../../src/content/site';

