            <h3>{c.title}</h3>
            <div className="meta">
              <span className="duration">{c.duration}</span>
            </div>
            <hr />
            <div className="learn-section">
              <p>You will learn</p>
              <ul>
                {c.learn.map((l, i) => (
                  <li key={i}>{l}</li>
