{"path": "src/components/Icons.tsx", "content": "import * as React from 'react';

type IconProps = { size?: number; className?: string };

const base = (size: number) => ({
  width: size,
  height: size,
  viewBox: '0 0 24 24',
  fill: 'none',
  stroke: 'currentColor',
  strokeWidth: 2,
  strokeLinecap: 'round' as const,
  strokeLinejoin: 'round' as const,
  'aria-hidden': true as const,
  focusable: 'false' as const,
});

export function CheckIcon({ size = 24, className }: IconProps) {
  return (
    <svg {...base(size)} className={className}>
      <circle cx="12" cy="12" r="10" />
      <path d="M8 12.5l3 3 5-6" />
    </svg>
  );
}

export function ClockIcon({ size = 20, className }: IconProps) {
  return (
    <svg {...base(size)} className={className}>
      <circle cx="12" cy="12" r="10" />
      <path d="M12 7v5l3 2" />
    </svg>
  );
}

export function AlertIcon({ size = 18, className }: IconProps) {
  return (
    <svg {...base(size)} className={className}>
      <circle cx="12" cy="12" r="10" />
      <path d="M12 7v6M12 16.5v.5" />
    </svg>
  );
}

export function ArrowIcon({ size = 18, className }: IconProps) {
  return (
    <svg {...base(size)} className={className}>
      <path d="M5 12h14M13 6l6 6-6 6" />
    </svg>
  );
}

export function MenuIcon({ size = 22, open = false }: IconProps & { open?: boolean }) {
  return (
    <svg {...base(size)}>
      {open ? <path d="M6 6l12 12M18 6L6 18" /> : <path d="M4 7h16M4 12h16M4 17h16" />}
    </svg>
  );
}

export function PillarIcon({ kind, size = 40 }: { kind: number; size?: number }) {
  const paths = [
    <path key="a" d="M4 19V9M10 19V5M16 19v-8M22 19H2" />,
    <path key="b" d="M3 9l9-5 9 5-9 5-9-5zM7 11.5V16c0 1.5 2.5 3 5 3s5-1.5 5-3v-4.5" />,
    <path key="c" d="M8 8l-5 4 5 4M16 8l5 4-5 4M14 5l-4 14" />,
  ];
  return (
    <svg {...base(size)} strokeWidth={1.6} className="pillar-icon">
      {paths[kind % paths.length]}
    </svg>
  );
}
"}

{"path": "src/components/Header.tsx", "content": "import * as React from 'react';
import { Link, NavLink, useLocation } from 'react-router-dom';
import { Wordmark } from './Wordmark';
import { MenuIcon } from './Icons';
import { NAV_LINKS, CTA } from '../content/site';

export default function Header() {
  const [menuOpen, setMenuOpen] = React.useState(false);
  const panelId = 'mobile-nav';
  const toggleMenu = () => setMenuOpen((prev) => !prev);
  const close = () => setMenuOpen(false);
  const location = useLocation();

  React.useEffect(() => {
    setMenuOpen(false);
  }, [location.pathname]);

  React.useEffect(() => {
    if (!menuOpen) return undefined;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setMenuOpen(false);
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [menuOpen]);

  return (
    <header className='site-header'>
      <div className='container header-inner'>
        <Wordmark />
        {/* Desktop nav */}
        <nav aria-label='Main' className='nav-desktop'>
          {NAV_LINKS.map((link) => (
            <NavLink key={link.to} to={link.to} className='nav-link'>
              {link.label}
            </NavLink>
          ))}
          <Link to={CTA.to} className='btn btn-primary btn-header'>
            {CTA.label}
          </Link>
        </nav>
        {/* Mobile menu button */}
        <button
          type='button'
          aria-controls={panelId}
          aria-expanded={menuOpen ? 'true' : 'false'}
          onClick={toggleMenu}
          className='menu-toggle'
        >
          <span>Menu</span>
          <MenuIcon open={menuOpen} />
        </button>
      </div>
      {menuOpen && (
        <nav id={panelId} aria-label='Mobile' className='nav-mobile'>
          <ul>
            {NAV_LINKS.map((link) => (
              <li key={link.to}>
                <NavLink to={link.to} className='nav-link' onClick={close}>
                  {link.label}
                </NavLink>
              </li>
            ))}
            <li>
              <Link to={CTA.to} className='btn btn-primary btn-block' onClick={close}>
                {CTA.label}
              </Link>
            </li>
          </ul>
        </nav>
      )}
    </header>
  );
}
"}

