{
  "issues": [
    {
      "issue": "Missing implementation of the About page placeholder tags and placeholder indication according to requirement R86 and R87. The founder cards lack visible \\\"Placeholder\\\" tags and explicit wording indicating content is placeholder, causing tests in __tests__/acceptance/about-render.test.ts that check for placeholder text to potentially fail.",
      "task_quote": "two founder cards with clearly marked placeholder content (name \\\"Founder Name\\\", role \\\"Co-founder & Principal Data Scientist\\\", a credentials list and a short bio, both marked as placeholders to be replaced)",
      "test": "/** @jest-environment jsdom */\\nimport * as React from 'react';\\nimport { render, screen } from '@testing-library/react';\\nimport { MemoryRouter } from 'react-router-dom';\\nimport AboutPage from '../src/pages/AboutPage';\\n\\ndescribe('About page placeholder founder cards', () => {\\n  test('REPRO: founder cards must show placeholder tags and replacement note', () => {\\n    render(\\n      <MemoryRouter>\\n        <AboutPage />\\n      </MemoryRouter>,\\n    );\\n    const nameElements = screen.getAllByText('Founder Name');\\n    expect(nameElements).toHaveLength(2);\\n    nameElements.forEach((el) => {\\n      const card = el.closest('article') || el.parentElement;\\n      const cardText = card?.textContent ?? '';\\n      expect(cardText).toMatch(/placeholder/i);\\n      expect(cardText).toMatch(/replace/i);\\n    });\\n  });\\n});"
    },
    {
      "issue": "The CSS token for accentText is not defined or used in THEME; requirement R114 expects text colours meeting WCAG AA contrast, and the contrast test in __tests__/acceptance/theme.test.ts checks THEME.accentText, which currently does not exist in src/theme/tokens.ts, causing the test to fail.",
      "task_quote": "Accessibility: semantic landmarks (header, nav, main, footer), every form field has a label, keyboard focus is visible, and text meets WCAG AA contrast.",
      "test": "/** @jest-environment node */\\nimport { THEME } from '../src/theme/tokens';\\n\\ndescribe('Theme tokens', () => {\\n  test('REPRO: THEME must include accentText token for contrast compliance', () => {\\n    expect((THEME as any).accentText).toBeDefined();\\n    expect(typeof (THEME as any).accentText).toBe('string');\\n  });\\n});"
    },
    {
      "issue": "The Menu button toggle does not have an accessible label indicating \"Menu\" for screen readers beyond the inner span, and the button lacks aria-controls linking to the mobile nav panel with matching id; while the rendering tests check for a button with name /menu/i and proper aria-expanded, the button inner text is wrapped in <span>, but the screen reader may not see it. Ensure the button has an accessible name (e.g., aria-label) matching \"Menu\".",
      "task_quote": "The header navigation collapses into a \"Menu\" button that opens and closes the links.",
      "test": "/** @jest-environment jsdom */\\nimport * as React from 'react';\\nimport { render, screen } from '@testing-library/react';\\nimport { MemoryRouter } from 'react-router-dom';\\nimport Header from '../src/components/Header';\\n\\ndescribe('Header mobile menu button accessibility', () => {\\n  test('REPRO: Menu button must have aria-label and aria-controls linking to a panel', () => {\\n    render(\\n      <MemoryRouter>\\n        <Header />\\n      </MemoryRouter>,\\n    );\\n    const button = screen.getByRole('button', { name: /menu/i });\\n    const ariaLabel = button.getAttribute('aria-label');\\n    expect(ariaLabel).toBeTruthy();\\n    expect(ariaLabel?.toLowerCase()).toContain('menu');\\n    const controlsId = button.getAttribute('aria-controls');\\n    expect(controlsId).toBeTruthy();\\n    const panel = document.getElementById(controlsId!);\\n    expect(panel).toBeTruthy();\\n  });\\n});"
    },
    {
      "issue": "The wordmark component does not render the SVG bell-curve mark when onDark prop is true; requirement R12 expects an inline SVG bell curve mark followed by the text \"The Bayes Group\". The SVG is present, but the fill/stroke color does not adjust for dark backgrounds. Ensure the SVG uses var(--color-accent-light) for dark mode.",
      "task_quote": "- **Wordmark:** an inline SVG bell curve (28×20, stroke 2.5px, `--color-accent`; `--color-accent-light` on navy) followed by \"The Bayes Group\" in serif 600 at 20px.",
      "test": "/** @jest-environment jsdom */\\nimport * as React from 'react';\\nimport { render, screen } from '@testing-library/react';\\nimport Wordmark from '../src/components/Wordmark';\\n\\ndescribe('Wordmark dark mode rendering', () => {\\n  test('REPRO: SVG must use accent-light variable when onDark prop is true', () => {\\n    render(<Wordmark onDark={true} />);\\n    const svg = screen.getByRole('img', { name: /the bayes group/i });\\n    expect(svg).toBeTruthy();\\n    const stroke = svg.getAttribute('stroke') ?? '';\\n    expect(stroke).toMatch(/var\\(--color-accent-light\\)/);\\n  });\\n});"
    },
    {
      "issue": "The About page values do not include descriptions in the rendered markup; requirement R88-R91 require values with titles and descriptions. Ensure the About page renders each value's description.",
      "task_quote": "four values: Evidence over hype; Build to transfer; Vendor-neutral; Responsible by design",
      "test": "/** @jest-environment jsdom */\\nimport * as React from 'react';\\nimport { render, screen } from '@testing-library/react';\\nimport { MemoryRouter } from 'react-router-dom';\\nimport AboutPage from '../src/pages/AboutPage';\\nimport { VALUES } from '../src/content/about';\\n\\ndescribe('About page values descriptions', () => {\\n  test('REPRO: each value description should be rendered', () => {\\n    render(\\n      <MemoryRouter>\\n        <AboutPage />\\n      </MemoryRouter>,\\n    );\\n    VALUES.forEach((value) => {\\n      const titleEl = screen.getByText(value.title);\\n      expect(titleEl).toBeTruthy();\\n      const descEl = screen.getByText(value.description);\\n      expect(descEl).toBeTruthy();\\n    });\\n  });\\n});"
    }
  ]
